\label{defn1}{\rm \cite{CD}
Let $v,k$ and $\lambda$ be positive integers. A 2-$(v,k,\lambda)$ design is a design $\mathbb{D}=(P,\mathcal{B})$ such that the following three conditions are satisfied:
\begin{itemize}
	\item [(i)] $|P|=v$;

	\item [(ii)] each block contains exactly $k$ points of $P$;

	\item [(iii)] every pair of distinct points is contained in exactly $\lambda$ blocks.
\end{itemize}
}

\label{defn2}{\rm \cite{CD, DS}
(1) A 2-$(v,k,\lambda)$ design is called {\it symmetric} if $v$ is equal to the number of blocks, equivalently, every two blocks share exactly $\lambda$ points.  

(2) A symmetric 2-design is said to have the {\it symmetric difference property}
or be an SDP design if given any three distinct blocks $B_1, B_2, B_3$ of the design, their symmetric difference $B_1\Delta B_2 \Delta B_3$ is either a block of the design or the complement of a block. 

(3) A 2-design is {\it quasi-symmetric} with intersection numbers $i$ and $j$, $(i < j)$ if any two blocks intersect in either $i$ or $j$ points.

}

\label{defn2@}{\rm 
  A 2-design is said to have the triple symmetric difference property or be a TSDP design if the symmetric difference $B_1 \Delta B_2 \Delta B_3$ is either a block of the design or the complement of a block for any three pairwise distinct blocks $B_1$, $B_2$, and $B_3$ of the design. 







}

\label{lem2}{\rm
   Let $f$ be a non-affine function in ${\mathcal{BF}_m}$ and $\sigma$ be a permutation of $\mathbb{F}^m_2$. Then $f \circ \sigma^{-1}$ is non-affine if and only if the $\mathbb{F}_2$-linear span of 
   $\{(f(x),\sigma x,1):x\in\mathbb{F}^m_2\}$ is $\mathbb{F}_2\times\mathbb{F}^m_2\times\mathbb{F}_2$.   }

Let \[
 G=\begin{pmatrix}
\cdots & 1 & \cdots\\
\cdots & (\sigma x)^T & \cdots \\
\cdots & f(x) & \cdots
\end{pmatrix}_{x\in\mathbb{F}^m_2}
\]We only need to prove that the rank of $G$ is $m+2$ if and only if $f \circ \sigma^{-1}$ is non-affine.
For any $u \in \mathbb{F}_{2}^{m}, t, s \in \mathbb{F}_{2}$, the Hamming weight of the vector $c(t, u, s)=(t, u, s)G$ is given as follows:
\begin{equation*}
    \begin{split}
        w(c(t, u, s))&=2^{m}-\sum_{x \in \mathbb{F}_{2}^{m}}\delta_{0, t+u \cdot \sigma x+sf(x)}\\
        &=2^{m}-\frac{1}{2}\sum_{x \in \mathbb{F}_{2}^{m}}(1+(-1)^{t+u \cdot \sigma x+sf(x)})\\
        &=
\begin{cases}
    2^{m-1}-\frac{1}{2}(-1)^{t}W_{f\circ \sigma^{-1}}(u), & \text{ if } s=1,\\
    2^{m-1}-(-1)^{t}2^{m-1}\delta_{{\bf{0}}, u}, & \text{ if } s=0.
\end{cases}
    \end{split}
\end{equation*}
Note that if $w(c(t, u, 0))=0$, then $u={\bf{0}},t=0$. If there is $(u_{0}, t_{0}) \in \mathbb{F}_{2}^{m} \times \mathbb{F}_{2}$ such that $w(c(t_{0}, u_{0}, 1))=0$, then $|W_{f\circ \sigma^{-1}}(u_{0})|=2^m$. In this case, the Parseval's identity guarantees that $W_{f\circ \sigma^{-1}}(x)=0$ for any $x \neq u_{0}$, and then $f\circ \sigma^{-1}$ is an affine function. Therefore, if $f \circ \sigma^{-1}$ is non-affine, then $w(c(t, u, s))=0$ if and only if $(t, u, s)=(0,{\bf{0}},0)$, and the rank of $G$ is $m+2$. Conversely, if $f \circ \sigma^{-1}$ is affine, then there is $(a, b) \in \mathbb{F}_{2}^{m} \times \mathbb{F}_{2}$ such that $f \circ \sigma^{-1}(x)=a \cdot x+b$, and $w(c(b, a, 1))=0$ since $W_{f \circ \sigma^{-1}}(a)=2^m(-1)^{b}$. Thus, if $f \circ \sigma^{-1}$ is affine, then the rank of $G$ is not $m+2$. This completes the proof.

\label{lem3.1}{\rm
For two subsets $P,B\subseteq \mathbb{F}^m_2$,
let $\mathbb{D}=(P,\{B^{f_b}:b\in B\})$ be an incidence structure associated with Boolean functions $f_b$ in $\mathcal{BF}_m$ corresponding to $b\in B$. The following statements are true.
\begin{itemize}
\item[(i)] The sum $\chi_u(B^{f_b})
=\frac{1}{2}\left(\chi_u(P)-W_{P,f_b}(u)\right)$, \text{ and the size of a block equals } 
$$\frac{1}{2}\left(|P|-W_{P,f_b}(\mathbf{0})\right).$$

\item[(ii)] The number of blocks containing a point $p\in P$ equals
$\frac{1}{2}\left(|B|-\sum_{b\in B}(-1)^{f_b(p)}\right).$

\item[(iii)] The number of blocks containing two distinct points $p,q\in P$ equals
$$\frac{1}{4}\left(|B|-\sum_{b\in B}(-1)^{f_b(p)}
 -\sum_{b\in B}(-1)^{f_b(q)}+\sum_{b\in B}(-1)^{f_b(p)+f_b(q)}\right).$$

\item[(iv)] The block intersection numbers of two distinct vectors $a,b\in B$ are
$$\frac{1}{4}\left(|P|-\sum_{p\in P}(-1)^{f_a(p)}
 -\sum_{p\in P}(-1)^{f_b(p)}+\sum_{p\in P}(-1)^{f_a(p)+f_b(p)}\right).$$
\end{itemize}
}

\label{cor3.2}{\rm
Let $P$ and $B$ be subsets of $\mathbb{F}^m_2$. A pair $(P,\{f_b\in\mathcal{BF}_m:b\in B\})$ induces a $2$-$(v, k, \lambda)$ design $\mathbb{D}=(P,\{B^{f_b}:b\in B\})$ if and only if the following three conditions hold;
\begin{itemize}
    \item [(i)] $W_{P,f_b}(\mathbf{0})=v-2k$ for all $b\in B$.

\item [(ii)] $\sum_{b\in B}(-1)^{f_b(p)}=|B|-2r_p$ is a constant for all $p\in P$, where $r_p$'s are replication numbers of $\mathbb{D}$.

\item[(iii)] $\sum_{b\in B}(-1)^{f_b(p)+f_b(q)}=4(\lambda-r_p)+|B|$ is a constant for all $p,q\in P$ with $p\neq q$.
\end{itemize}
}

\label{exam3.3} 
{\rm
Let ${\mathcal{C}}$ be an LCD linear code of length $m$, and let $f_b(x)=b\cdot x$ for $b\in {\mathcal{C}}^*$ be a Boolean function in $\mathcal{BF}_m$. Then
 the pair $({\mathcal{C}}^*,\{f_b\in\mathcal{BF}_m:b\in {\mathcal{C}}^*\})$ induces a symmetric 2-design with parameters $(|{\mathcal{C}}|-1,|{\mathcal{C}}|/2,|{\mathcal{C}}|/4)$.                                                                                                                           

 }

\label{rmk3.4}
 	{\rm
 	 Note that this symmetric $2$-design in Proposition \ref{exam3.3} is the complement of a point-hyperplane design which is already known in \cite[Theorem 6.20]{CD}. 



  }

\label{thm3.7}  {\rm $($\cite{B,K,DS,MW}$)$
Let $\mathbb{D}$ be a symmetric 2-design with $2^m$ points. The following statements are equivalent.
\begin{itemize}
    \item[(i)] $\mathbb{D}$ is a TSDP design with parameters $(\dag)$.


    \item[(ii)] $\mathbb{D}$ is isomorphic to some addition design derived from a bent function in $\mathcal{BF}_m$.

    \item[(iii)] The $2$-rank of $\mathbb{D}$ with parameters $(\dag)$ is $m+2$.


   \item[(iv)] The binary linear code $\mathcal{C}_{\mathbb{D}}$ of $\mathbb{D}$ is generated by the first order Reed-Muller code with parameters $[2^m,m,2^{m-1}]$ and the characteristic vector of a difference set.
\end{itemize}
}

\label{thm3.8}{\rm                                                                                                                                                                                                                                                                                                                                                                                                                                                                  

Let $f$ be a bent function in $\mathcal{BF}_m$  with $f^*(\mathbf{0})=0$. The following statements are equivalent.
\begin{itemize}
    \item[(i)] $f$ is quadratic.
    \item[(ii)] The addition design $\mathbb{AD}_f$ and translation design $\mathbb{TD}_f$ derived from $f$ are isomorphic with an identity map on point sets and some linear permutation map on block sets.

    \end{itemize}
    }

(i) $\Longrightarrow$ (ii): It was verified in \cite[Theorem 11.9]{B}.                                         






















(ii) $\Longrightarrow$ (i): Assume that $f(p)+f^*(\pi b)+p\cdot\pi b =f(p+b)$ for some linear permutation $\pi$ of $\mathbb{F}_2^m$. By plugging $p=\mathbf{0}$, we have $f^*(\pi b)=f(b)+f(\mathbf{0})$ for all $b\in\mathbb{F}^m_2$, and so  
\begin{align}\label{eqn:(6)}
    f(p)+f(b)+f(p+b)=p\cdot\pi b+f(\mathbf{0})
\end{align}
for all $p,b\in\mathbb{F}^m_2$. Let $g$ be the function of $x,y\in \mathbb{F}_2^m$ defined by
\begin{align}\label{eqn:(7)}
	g(x,y)=f(x)+f(y)+f(x+y)+x\cdot\pi y+f(\mathbf{0}).
\end{align}
Then $g(p,b)=0$ for all $p,b\in\mathbb{F}^m_2$ by Eq. (\ref{eqn:(6)}), and so the Boolean $g$ is identically zero, that is, $g\equiv 0$. Notice that the degree of $f(x)+f(y)+f(x+y)$ is equal to the degree of $f$. Observe that the degree of $x\cdot\pi y$ is two, since $\pi$ is linear. Hence $f$ is quadratic using Eq. (\ref{eqn:(7)}). This completes the proof.

\label{ex2.9}

	{\rm
	{Let $f(x_1,x_2,x_3,y_1,y_2,y_3)=x_1y_1+x_2y_2+x_3y_3$ be an M-M bent function in $\mathcal{BF}_6$. Let $\pi$ be the permutation of $\mathbb{F}_2^6$ defined as $\pi(x_1,x_2,x_3,y_1,y_2,y_3)=(y_1,y_2,y_3,x_1,x_2,x_3)$. One can check that $f(x)+f^{*}(\pi b)+x\cdot\pi b=f(x+b),$}






	{where $x=(x_1,x_2,x_3,y_1,y_2,y_3)$ and $b=(a_1,a_2,a_3,b_1,b_2,b_3)$ in ${\mathbb F}^6_2$. Thus the addition design and translation design derived from $f$ are isomorphic with an identity map on point sets and $\pi$ being a linear permutation on block sets.}
 }

\label{lem.SDP}{\rm
	{Let $P$ and $B$ be subsets of $\mathbb{F}^m_2$. 
 A            
 2-design induced the blocks $B^{f_b}$ for $b\in\mathbb{F}^m_2$ has the TSDP if and only if for any $b_1,b_2,b_3\in B$, there is a $b_4\in B$ such that $f_{b_1}(x)+f_{b_2}(x)+f_{b_3}(x)=f_{b_4}(x)+\varepsilon_{b_4}$ for all $x\in P,$ where $\varepsilon_{b_4}$ is a constant in $\mathbb{F}_2$.}
	}

\label{thmB3}{\rm
{Let $f(x,y)=x\cdot y+ g(y)$ in $\mathcal{BF}_{2m}$ be an M-M bent function. Then the translation design $\mathbb{TD}_f$ derived from $f$ has the TSDP, {which is equivalent to having minimal rank $2m+2$}, if and only if the degree of $g$ is less than or equal to three.

 } 
}

From this point onward, we represent $f_1(x)\fallingdotseq f_2(x)$ if $f_1(x)=f_2(x)+s$ for all $x\in\mathbb{F}_2^n$ and a  constant $s\in\mathbb{F}_2$.

	{($\Leftarrow$):  Let $f(x,y)=x\cdot y+g(y)$ with deg $g \le 3$.}
		{By Lemma \ref{lem.SDP}, we have to show that for any $a_1,a_2,a_3,b_1,b_2,b_3\in\mathbb{F}_2^m$, there are $a_4,b_4\in\mathbb{F}_2^m$ such that $f(x+a_1,y+b_1)+f(x+a_2,y+b_2)+f(x+a_3,y+b_3)\fallingdotseq f(x+a_4,y+b_4)$. Observe that $x+a_1$ and $y+b_1$ can be treated as $x$ and $y$, respectively.  It is thus enough to show that for any $a,b,c,d\in\mathbb{F}_2^m$, there are $\alpha,\beta\in\mathbb{F}_2^m$ such that}
	\begin{align}\label{eqn:SDP}
		&f(x,y)+f(x+a,y+b)+f(x+c,y+d)\nonumber\\
		&\fallingdotseq f(x+\alpha,y+\beta)
	\end{align}
{for all $ x,y\in \mathbb{F}_2^m$.}
{Since $f(x,y)=x\cdot y +g(y)$, then}
\begin{multline*}
	f(x,y)+f(x+a,y+b)+f(x+c,y+d)\\
	\fallingdotseq (x+a+c)\cdot(y+b+d)+g(y)+g(y+b)+g(y+d).
\end{multline*}
{If $g$ is a constant or linear, then $g(y)+g(y+b)+g(y+d)\fallingdotseq g(y+b+d)$, and Eq. (\ref{eqn:SDP}) holds when $\alpha=a+c$ and $\beta=b+d$.}
{Next we consider the quadratic Boolean function $h_1(x_1,x_2)=x_1 x_2$. Then}
\begin{align*}
&h_1(x_1,x_2)+h_1(x_1+a_1,x_2+a_2)+h_1(x_1+b_1,x_2+b_2)\\ &=x_1x_2+(a_2+b_2)x_1+(a_1+b_1)x_2+a_1a_2+b_1b_2\\ &\fallingdotseq h_1(x_1+a_1+b_1,x_2+a_2+b_2).
\end{align*}
{If $g$ is a quadratic Boolean function, then $g(y)+g(y+b)+g(y+d)\fallingdotseq g(y+b+d)$ since $g$ is a linear combination of monomials whose degree is less than or equal to two. Therefore Eq. (\ref{eqn:SDP}) holds when $\alpha=a+c$ and $\beta=b+d$.}
Next we consider the cubic Boolean function $h_2(x_1,x_2,x_3)=x_1x_2x_3$. Then,
\begin{align*}
	&h_2(x_1,x_2,x_3)+h_2(x_1+a_1,x_2+a_2,x_3+a_3)\\
	&+h_2(x_1+b_1,x_2+b_2,x_3+b_3)\\
	&=x_1x_2x_3+(a_3+b_3)x_1x_2+(a_2+b_2)x_1x_3+(a_1+b_1)x_2x_3\\
	&\quad+(a_2a_3+b_2b_3)x_1+(a_1a_3+b_1b_3)x_2+(a_1a_2+b_1b_2)x_3\\
	&+a_1a_2a_3+b_1b_2b_3\\
	&\fallingdotseq h_2(x_1+a_1+b_1,x_2+a_2+b_2,x_3+a_3+b_3)\\
	&\quad +(a_2b_3+a_3b_2)x_1+(a_1b_3+a_3b_1)x_2+(a_1b_2+a_2b_1)x_3.
\end{align*}
Thus if $g$ is a cubic Boolean function, then
\begin{align*}
	g(y)+g(y+b)+g(y+d)\fallingdotseq g(y+b+d)+\sum_{i=1}^{m}\gamma_i y_i
\end{align*}
where $\gamma_i\in\mathbb{F}_2$ are constants which depend on $b$ and $d$, and $y\in\mathbb{F}_2^m$.
That is, 
\begin{align*}
	&f(x,y)+f(x+a,y+b)+f(x+c,y+d)\\
	&\fallingdotseq (x+a+c)\cdot(y+b+d)+g(y+b+d)+\sum_{i=1}^{m}\gamma_i y_i\\
	&\fallingdotseq (x+a+c+\gamma)\cdot(y+b+d)+g(y+b+d)\\
	&=f(x+a+c+\gamma,y+b+d)
\end{align*}
Therefore, $f(x,y)=x\cdot y+g(y)$ induces a {TSDP} design when deg $g \le 3$.


	{($\Rightarrow$): Let $f(x,y)=x\cdot y+g(y)$ be an M-M bent function with deg $g \ge 4$. Assume that $f$ induces a {TSDP} design. { By Lemma \ref{lem.SDP}}, for all $a,b,c,d\in\mathbb{F}_2^m$, there exist $\alpha,\beta\in\mathbb{F}_2^m$ such that}
\begin{align}\label{eqn:SDP2}
	&f(x,y)+f(x+a,y+b)+f(x+c,y+d)\nonumber\\
	&\fallingdotseq f(x+\alpha,y+\beta).
\end{align}
If $y={\bf 0}$ in Eq. (\ref{eqn:SDP2}), 
\begin{align*}
	&f(x,0)+f(x+a,b)+f(x+c,d)\\
	&=(x+a)\cdot b+(x+c)\cdot d +g(0)+g(b)+g(d)\fallingdotseq x\cdot (b+d).
\end{align*}
Since $f(x+\alpha,\beta)=(x+\alpha)\cdot \beta+g(\beta)\fallingdotseq x\cdot \beta$, we obtain that $x\cdot (b+d)\fallingdotseq x\cdot \beta$. So it follows that $\beta=b+d$.
If $x={\bf 0}$ in Eq. (\ref{eqn:SDP2}),
\begin{align*}
	&f(0,y)+f(a,y+b)+f(c,y+d)\\
	&=a\cdot(y+b)+c\cdot(y+d)+g(y)+g(y+b)+g(y+d)\\
	&\fallingdotseq(a+c)\cdot y +g(y)+g(y+b)+g(y+d)
\end{align*}
Note that $f(\alpha,y+\beta)=\alpha\cdot(y+\beta)+g(y+\beta)\fallingdotseq \alpha\cdot y+g(y+\beta)$. Since $\beta=b+d$, we have
\begin{align*}
	&(a+c)\cdot y+g(y)+g(y+b)+g(y+d)\\
	&\fallingdotseq \alpha \cdot y+g(y+b+d),
\end{align*}
which implies that
\begin{align}{\label{eqn:SDP3}}
	&g(y)+g(y+b)+g(y+d)+g(y+b+d)\nonumber\\
	&\fallingdotseq (a+c+\alpha)\cdot y.
\end{align}
Let $g$ be a Boolean function of degree $k\geq 4$ that contains at least one monomial $h_1(y_1,\ldots,y_m):=\prod_{i=1}^{k}y_i$ of degree $k$. Then the degree of $h_1(y)+h_1(y+b)+h_1(y+d)+h_1(y+b+d)$ is $k-2$, which implies that the degree of $g(y)+g(y+b)+g(y+d)+g(y+b+d)$ in Eq. \eqref{eqn:SDP3}  is at most $k-2$. 

{Now let $g(x)=h(x)+r(x),$ where $h(x)$ is a Boolean function with degree $k$ terms and each term involves $\prod_{i=1}^{k-2}y_i$, and $r(x)$ is remained terms of $g(x)$. Then $h(x)=\prod_{i=1}^{k-2}y_i\sum_{(i,j)\in I}y_iy_j$ for some subset $I\subset \{1,\ldots, m\}\times\{1,\ldots, m\}$. Note that $I$ is nonempty, since $(k-1,k-2)\in I$.}

{It is obvious that $h_1(y)+h_1(y+b)+h_1(y+d)+h_1(y+b+d)$ consists of a $y_1y_2\cdots y_{k-2}$ term with coefficient $b_{k-1}d_k+b_kd_{k-1}$. Then the coefficient of $\prod_{i=1}^{k-2}y_i$ in $g(y)+g(y+b)+g(y+d)+g(y+b+d)$, which is the same as the coefficient of $\prod_{i=1}^{k-2}y_i$ in $h(y)+h(y+b)+h(y+d)+h(y+b+d)$, is $\sum_{(i,j)\in I}{b_id_j+b_jd_i}$. Therefore the coefficient of $\prod_{i=1}^{k-2}y_i$ is not identically zero, and it implies that the degree of $g(y)+g(y+b)+g(y+d)+g(y+b+d)$ is $k-2$ which is at least $2$. This is a contradiction to (\ref{eqn:SDP3}) and completes the proof.}

