{\rm  \label{thm 2.23} \cite{DN} 
For an integer $r$ $(0\leq r < m)$, let $f$ be an $r$-plateaued function in $\mathcal{BF}_m,$ and let $P=S_f$ be the Walsh support of $f$. We can write $W_f(x)=(-1)^{g(x)}2^{\frac{m+r}{2}}1_P(x)$ for some $g$ in $\mathcal{BF}_m$. For each $b\in \mathbb{F}^m_2$, let $f_b(x)=b\cdot x+f(b)+g(x)$. Then a pair $(P,\{f_b\in\mathcal{BF}_m:b\in\mathbb{F}^m_2\})$ induces a 2-design $\mathbb{AD}_f=(P,\{B^{f_b}:b\in \mathbb{F}^m_2\})$ with parameters $(2^{m-r},2^{m-r-1}-2^{\frac{m-r-2}{2}},2^{m-2}-2^{\frac{{m+r-2}}{2}})$. The intersection numbers are $2^{m-r-2}-2^{\frac{m-r-2}{2}}+2^{-2-r}(-1)^{f(a)+f(b)}C_f(a+b)$
for $a,b\in\mathbb{F}^m_2$. If $r\neq0$, then $\mathbb{AD}_f$ is a non-symmetric 2-design. We call $\mathbb{AD}_f$ the addition design of $f$.
}

\label{prop2}{\rm 
    Let $f$ be an $r$-plateaued function in $\mathcal{BF}_m$ which is not bent and let for each $b \in \mathbb{F}_{2}^{m}$, $f_{b}(x)=f(x+b) \text{ for all } x \in \mathbb{F}_{2}^{m}$. Then the third condition in Corollary \ref{cor3.2} holds if and only if either $f$ is an affine function in  $\mathcal{BF}_1$ or $f$ is a constant function. 
    }

The third condition in Corollary \ref{cor3.2} is equivalent to that $|\{x \in \mathbb{F}_{2}^{m}: f(x)+f(x+a)=0\}|$ is a constant for any $a \neq \bf{0}$. Assume that $|\{x \in \mathbb{F}_{2}^{m}: f(x)+f(x+a)=0\}|$ is a constant for any $a \neq\bf{0}$ and denoted the constant by $\ell$. Then 
\begin{equation*}
\begin{split}
& (2^m-1)\ell+2^m=\sum_{a \in \mathbb{F}_{2}^{m}}|\{x \in \mathbb{F}_{2}^{m}: f(x)+f(x+a)=0\}|\\
 &=\frac{1}{2}\sum_{a, x \in \mathbb{F}_{2}^{m}}\sum_{z \in \mathbb{F}_{2}}(-1)^{(f(x)+f(x+a))z}\\
 &=\frac{1}{2}\sum_{x \in \mathbb{F}_{2}^{m}}\sum_{z \in \mathbb{F}_{2}}(-1)^{zf(x)}\sum_{a \in \mathbb{F}_{2}^{m}}(-1)^{zf(x+a)}\\
 &=\frac{1}{2}\sum_{z \in \mathbb{F}_{2}}\sum_{x \in \mathbb{F}_{2}^{m}}(-1)^{zf(x)}\sum_{a \in \mathbb{F}_{2}^{m}}(-1)^{zf(a)}\\
 &=2^{2m-1}+\frac{1}{2}W_{f}({\bf{0}})^{2},
\end{split}
\end{equation*}
which implies that $\ell=\frac{2^{2m-1}-2^m+\frac{1}{2}W_{f}({\bf{0}})^{2}}{2^m-1}$. If ${\bf{0}} \notin S_{f}$, then $2^m-1 \mid 2^{m}(2^{m-1}-1)$, which implies that $m=r=1$, and so $f(x)=x+s$ for $x,s \in \mathbb{F}_{2}$. If ${\bf{0}} \in S_{f}$ (that is, $W_{f}({\bf{0}})^{2}=2^{m+r}$), then $2^m-1 \mid 2^m(2^{m-1}+2^{r-1}-1)$, which implies that $r=m$, and so $f$ is a constant function as ${\bf{0}} \in S_{f}$. This completes  the proof.

\label{lem4.3}
 {\rm For an integer $r$ $(0\leq r\leq m)$, let $f$ be an $r$-plateaued function in $\mathcal{BF}_m$ and let $S_f$ be represented as $S_f=a+E$ for some subset $E$ of $\mathbb F_2^m$ and $a\in S_f$. Then the following statements are equivalent.
\begin{itemize}
    \item [(i)] The addition design  $\mathbb{AD}_f$ is simple.


     \item [(ii)] $f$ has no nonzero linear structure.


      \item [(iii)] The maximal number of linearly independent vectors in $E$ is equal to $m$. 

      \item [(iv)] A generator matrix of the linear code $\mathcal{C}_{\mathbb{AD}_{f}}$ of the design $\mathbb{AD}_{f}$ is $G_{f}$, where 
      \[
    G_f=\begin{pmatrix}
   \cdots & 1 & \cdots\\
   \cdots & x^T & \cdots \\
   \cdots & f(x) & \cdots
  \end{pmatrix}_{x\in\mathbb{F}^m_2}.\] 
\end{itemize}
}

\label{thm4.7}{\rm 








Let $\mathbb{D}$ be a simple $2$-design with $2^{m-r}$ points for some integer $0 \leq r < m$. The following statements are equivalent.
\begin{itemize}
    \item[(i)] $\mathbb{D}$ has the TSDP with parameters 
    $2$-$(2^{m-r},2^{m-r-1}-2^{\frac{m-r-2}{2}},2^{m-2}-2^{\frac{{m+r-2}}{2}})$.


    \item[(ii)] $\mathbb{D}$ is isomorphic to some addition design derived from an $r$-plateaued function in $\mathcal{BF}_m$ with no nonzero linear structure.

    \item[(iii)] The 2-rank of                     
    $\mathbb{D}$ with parameters  $2$-$(2^{m-r},2^{m-r-1}-2^{\frac{m-r-2}{2}},2^{m-2}-2^{\frac{{m+r-2}}{2}})$ is $m+2$, namely, $\operatorname{rank}_2(M(\mathbb{D}))=m+2$, and the first order Reed-Muller code $\mathrm{RM}(1,m)$ is a subcode of $\mathcal{C}_{\mathbb{D}}$.
