b \cdot x+g^{*}(b)=\sigma b \cdot \pi x+f^{*}(\sigma b).
$
Let us extend $\sigma$ by defining $\sigma{\bf{0}}={\bf{0}}$. Then $\sigma$ is a permutation of $\mathbb{F}_{2}^{m}$. By the parameters of $\mathbb{D}_{f}$ and $\mathbb{D}_{g}$, we have $g^{*}({\bf{0}})=f^{*}({\bf{0}})$. Since $\sigma{\bf{0}}={\bf{0}}$ and  $g^{*}( {\bf{0}})=f^{*}({\bf{0}})$, then for any $x \in D_{g}$, 
\begin{equation}\label{Eq35}
    {\bf{0}} \cdot x+g^{*}({\bf{0}})=\sigma {\bf{0}} \cdot \pi x+f^{*}(\sigma {\bf{0}})
\end{equation}
Therefore for any $b \in \mathbb{F}_{2}^{m}$ and $x \in D_{g}$, we have
\begin{equation}\label{Eq36}
b \cdot x+g^{*}(b)=\sigma b \cdot \pi x+f^{*}(\sigma b).
\end{equation}
Plugging $x= {\bf{0}}$ into Eq. \eqref{Eq36}, for any $b \in \mathbb{F}_{2}^{m}$, we have
\begin{equation}\label{Eq37}
    g^{*}(b)=\sigma b \cdot \pi  {\bf{0}}+f^{*}(\sigma b).
\end{equation}
Adding Eqs.~\eqref{Eq36} and  \eqref{Eq37}, for any $b \in \mathbb{F}_{2}^{m}$ and $x \in D_{g}$, we have
\begin{equation}\label{Eq38}
b \cdot x=\sigma b \cdot (\pi x+\pi {\bf{0}}).
\end{equation}
For any $b, b' \in \mathbb{F}_{2}^{m}$ and $x \in D_{g}$, by Eq. \eqref{Eq38}, we have
\begin{eqnarray}\label{Eq39}
    &\sigma (b+b') \cdot (\pi x+ \pi {\bf{0}})=(b+b') \cdot x=b \cdot x+b' \cdot x\nonumber\\
    &= (\sigma b+\sigma b') \cdot (\pi x+ \pi {\bf{0}}).
\end{eqnarray}
Let $E_{f}=D_{f}+\pi {\bf{0}}$. By the proof of Theorem \ref{thmmm}, $E_{f}$ contains a basis of $\mathbb{F}_{2}^{m}$. Hence, Eq. \eqref{Eq39} implies that $\sigma(b+b')=\sigma b+\sigma b'$ for any $b, b' \in \mathbb{F}_{2}^{m}$, that is, $\sigma$ is a linear permutation of $\mathbb{F}_{2}^{m}$. Denote $\sigma x=xA$ for $A \in \operatorname{GL}_{m}(\mathbb{F}_{2})$ and $c \in \mathbb{F}_{2}^{m}$. By Eq. \eqref{Eq37}, for any $x \in \mathbb{F}_{2}^{m}$. we have
\begin{equation*}
\begin{split}
   &2^{\frac{m}{2}}(-1)^{g(x)}=W_{g^{*}}(x)=\sum_{b \in \mathbb{F}_{2}^{m}}(-1)^{f^{*}(bA)+bA \cdot \pi {\bf{0}}+b \cdot x}\\
   &=\sum_{b \in \mathbb{F}_{2}^{m}}(-1)^{f^{*}(b)+b \cdot (\pi {\bf{0}}+x(A^{-1})^{T})}\\
   &=W_{f^{*}}(\pi {\bf{0}}+x(A^{-1})^{T})=2^{\frac{m}{2}}(-1)^{f(\pi {\bf{0}}+x(A^{-1})^{T}))}.
\end{split}
\end{equation*}
Thus $g$ and $f$ are affine equivalent with $g(x)=f(\pi {\bf{0}}+x(A^{-1})^{T})).$

This completes this proof.

