\label{thm14}{\rm
Let $g$ and $h$ be bent functions in $\mathcal{BF}_m$ satisfying that
$g+h$ is bent and $(g+h)^*=g^*+h^*$. For each $b\in \mathbb{F}^m_2$, let $f_b(x)=g(b)+h(x+b)+(g+h)(x)$. Then the following statements hold.
\begin{itemize}
    \item [(i)] A pair $(\mathbb{F}^{m}_2,f_b\in\mathcal{BF}_m:b\in\mathbb{F}^{m}_2\})$ induces a symmetric 2-design with parameters $(2^m,2^{m-1}-2^{\frac{m}{2}-1},2^{m-2}-2^{\frac{m}{2}-1})$, denoted this design by $\mathbb{D}_{g,h}$.



    \item[(ii)] The addition design $\mathbb{AD}_f$ derived from a bent function $f\in\mathcal{BF}_m$ and the design $\mathbb{D}_{g,h}$ have the same parameters. If the 2-rank of $\mathbb{TD}_h$ is larger than $m+2$, then $\mathbb{D}_{g,h}$ and $\mathbb{AD}_f$ are not isomorphic.

\end{itemize}

}

(i). Let $g$ and $h$ be bent functions in $\mathcal{BF}_m$ satisfying that
$g+h$ is bent and $(g+h)^*=g^*+h^*$.
We have 
\begin{multline*}
 C_{g,h}(a)=\frac{1}{2^m}\sum_{x\in\mathbb{F}^m_2}W_g(x)W_h(x)(-1)^{a\cdot x}\\
 =\sum_{x\in\mathbb{F}^m_2}(-1)^{a\cdot x+g^*(x)+h^*(x)}
 =\sum_{x\in\mathbb{F}^m_2}(-1)^{a\cdot x+(g+h)^*(x)}\\
 =2^{\frac{m}{2}}(-1)^{(g+h)(a)}.
\end{multline*}
It follows that for $b\in\mathbb{F}^{m}_2$,  
\begin{multline*}
 W_{\mathbb{F}^m_2,f_b}(\mathbf{0})=\sum_{p\in {\mathbb{F}^{m}_2}}(-1)^{g(b)+h(p+b)+(g+h)(p)}\\
=(-1)^{g(b)}C_{g+h,h}(b)=(-1)^{g(b)}2^{\frac{m}{2}}(-1)^{(g+h)(b)+h(b)}=2^{\frac{m}{2}}
\end{multline*}
and for two distinct points $p,q\in\mathbb{F}^m_2$,
\begin{multline*}
  \sum_{b\in \mathbb{F}^m_2}(-1)^{f_b(p)+f_b(q)}\\=\sum_{b\in \mathbb{F}^m_2}(-1)^{g(b)+h(p+b)+(g+h)(p)+g(b)+h(q+b)+(g+h)(q)}\\
=(-1)^{(g+h)(p)+(g+h)(q)}\sum_{b\in \mathbb{F}^m_2}(-1)^{h(p+b)+h(q+b)}  \\
=(-1)^{(g+h)(p)+(g+h)(q)}{C_{h}}(p+q)=0.
\end{multline*}
The parameters are computed by those three values of summations using  Corollary \ref{cor3.2}.






















(ii). Assume, to the contrary, that $\mathbb{D}_{g,h}$ and $\mathbb{AD}_f$ are isomorphic. Then
\begin{align}\label{eqn38}
    f(\sigma p)+f^*(\pi b)+\sigma p\cdot \pi b\nonumber\\=g(b)+h(p+b)+(g+h)(p) \text{ for all } p,b\in\mathbb{F}^m_2
\end{align}
and for some permutations $\sigma, \pi$ of $\mathbb{F}^m_2$. 





By plugging $b={\bf{0}}$ and $p={\bf{0}}$ into Eq. \eqref{eqn38}, respectively,  
\begin{align}\label{39}
    f(\sigma p)+\sigma p\cdot \pi{\bf{0}}=h(p)+(g+h)(p)+f^*(\pi{\bf{0}})+g({\bf{0}}),\\ 
    f^*(\pi b)+\sigma{\bf{0}}\cdot\pi b=g(b)+h(b)+(g+h)({\bf{0}})+f(\sigma{\bf{0}}) \label{40}
\end{align} 
for all $p,b\in{\mathbb F}^m_2$.
By adding Eqs. \eqref{eqn38}, \eqref{39} and \eqref{40}, we have 
\begin{eqnarray}\label{41}
&\bar{\sigma}p\cdot\bar{\pi}b=h(p+b)+h(p)+h(b)+h({\bf{0}})\nonumber\\
&+f(\sigma{\bf{0}})+f^*(\pi{\bf{0}})+\sigma{\bf0}\cdot\pi{\bf0}
\end{eqnarray}
for all $p,b\in{\mathbb F}^m_2$, where $\bar{\sigma}p=\sigma p+\sigma{\bf{0}}$ and $\bar{\pi}b=\pi b+\pi{\bf{0}}$. By plugging $b={\bf{0}}$ into Eq. \eqref{40}, we have 
$\bar{\sigma}p\cdot\bar{\pi}b=h(p+b)+h(p)+h(b)+h({\bf{0}})=B_h(b,p)$ for all $p,b\in{\mathbb F}^m_2$. Since $B_h(b,p)=B_h(p,b)$, then $\tau:=\bar{\pi}\circ\bar{\sigma}^{-1}$ is a linear permutation of $\mathbb{F}^m_2$. From Eq. \eqref{41}, we have 
\begin{eqnarray}\label{42}
& (\tau^*\circ\tau^{-1}b)\cdot p=\tau p\cdot \tau^{-1}b=h(\bar{\pi}^{-1} p+\bar{\sigma}^{-1}b)\nonumber\\
&+h(\bar{\pi}^{-1}p)+h(\bar{\sigma}^{-1}b)+h({\bf{0}}) \end{eqnarray} 
 for all $p,b\in{\mathbb F}^m_2$, where $\tau^*$ is the adjoint permutation of $\tau$.
We claim that both $h\circ \bar{\sigma}^{-1}$ and $h\circ \bar{\pi}^{-1}$ are non-affine. To get a contradiction, we may assume that $h\circ \bar{\pi}^{-1}$ is affine, and so $h\circ \bar{\pi}^{-1}(p)=a\cdot p+\varepsilon$ for some $a\in\mathbb{F}^m_2$ and $\varepsilon\in\mathbb{F}_2$. By Eq. \eqref{42}, we have
\begin{eqnarray*}
    &W_h({\bf{0}})=\sum_{p\in\mathbb{F}^m_2}(-1)^{h(\bar{\pi}^{-1}p+\bar{\sigma}^{-1}b)}\\
    &=(-1)^{h(\bar{\sigma}^{-1}b)+h(\bf{0})}\sum_{p\in\mathbb{F}^m_2}(-1)^{h(\bar{\pi}^{-1}p)+\tau p\cdot\tau^{-1}b}\\
    &=(-1)^{h(\bar{\sigma}^{-1}b)+h(\bf{0})}\sum_{p\in\mathbb{F}^m_2}(-1)^{a\cdot p+\varepsilon+p\cdot (\tau^*\circ\tau^{-1}b)}\\
    &=(-1)^{h(\bar{\sigma}^{-1}b)+h(\bf{0})+\varepsilon}2^m\delta_{a,\tau^*\circ\tau^{-1}b},
\end{eqnarray*}
which contradicts that $h$ is bent. This proves our claim. It then follows from Lemma \ref{thm6} that the 2-rank of $\mathbb{TD}_h$ is $m+2$, which is a contradiction to our assumption.

{\rm \label{openpro4}


 Prove that the 2-ranks of designs $\mathbb{D}_{g,h}$ and $\mathbb{TD}_h$  in Theorem \ref{thm14}
  are equal.

}
